describe('Notification Bell Badge Count', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should display badge count when notifications exist', () => {
    // Intercept the API call to fetch notifications
    cy.intercept('GET', '/api/notifications').as('getNotifications');

    // Click the notification bell icon
    cy.get('[data-testid="notification-bell-icon"]').click();

    // Wait for the API response
    cy.wait('@getNotifications');

    // Verify the badge count is displayed
    cy.get('[data-testid="notification-badge-count"]').should('be.visible');
    cy.get('[data-testid="notification-badge-count"]').should('contain', '3');

    // Verify the badge has the correct styling
    cy.get('[data-testid="notification-badge-count"]').should('have.class', 'badge-active');

    // Verify the notification dropdown is visible
    cy.get('[data-testid="notification-dropdown"]').should('be.visible');

    // Verify notification items are displayed
    cy.get('[data-testid="notification-item"]').should('have.length', 3);
  });

  it('should not display badge when no notifications exist', () => {
    // Intercept the API call and return an empty array
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: []
    }).as('getNotificationsEmpty');

    // Click the notification bell icon
    cy.get('[data-testid="notification-bell-icon"]').click();

    // Wait for the API response
    cy.wait('@getNotificationsEmpty');

    // Verify the badge count is not displayed
    cy.get('[data-testid="notification-badge-count"]').should('not.exist');

    // Verify the notification dropdown is still visible but empty
    cy.get('[data-testid="notification-dropdown"]').should('be.visible');

    // Verify no notification items are displayed
    cy.get('[data-testid="notification-item"]').should('not.exist');

    // Verify a "No notifications" message is shown
    cy.get('[data-testid="no-notifications-message"]').should('be.visible');
    cy.get('[data-testid="no-notifications-message"]').should('contain', 'No new notifications');
  });
});
